def pre_command(ctx):
    c = ctx['command']
    for p in c['paths']:
        if c['name'] == 'cat' and p.startswith('/repo/sealed/'):
            return {'deny': 'written by ' + ctx['profile']}
    return None

def pre_command(ctx):
    c = ctx['command']
    for p in c['paths']:
        if c['name'] == 'rm' and p.startswith('/scratch/askme/'):
            return {'ask': 'scripted sign-off'}
    return None

def pre_command(ctx):
    for p in ctx['command']['paths']:
        if 'marker' in contents(p):
            return {'deny': 'marked by ' + ctx['profile']}
    return None

def pre_ops(ctx):
    op = ctx['op']
    if op['write'] and op['path'].startswith('/scratch/cold/'):
        return {'deny': 'cold by ' + ctx['profile']}
    return None

def pre_session(ctx):
    if ctx['write']['key'].startswith('AWS_'):
        return {'deny': 'credentials are set by the operator'}
    return None

def contents(path):
    try:
        return open(path).read()
    except OSError:
        return ''

function preCommand(ctx) {
  const c = ctx.command
  const hit = c.name === 'cat' && c.paths.some((p) => p.startsWith('/repo/sealed/'))
  return hit ? {deny: 'sealed by ' + ctx.profile} : null
}

function preOps(ctx) {
  const op = ctx.op
  return op.write && op.path.startsWith('/scratch/cold/') ? {deny: 'cold by ' + ctx.profile} : null
}
function preSession(ctx) {
  return ctx.write.key.startsWith('AWS_') ? {deny: 'credentials are set by the operator'} : null
}
